//! The Markdown export: one file per book in `.shelfgauge/annotations/`.
//!
//! The files are generated from the database, one way only: edits to them are never
//! read back. A book's file is rewritten atomically (temporary file + rename) after
//! every change to its annotations; its name is
//! `<Authors> — <Title> (<short key>).md`, sanitized for Windows, macOS and Linux. The
//! short key (a hash of the content key) finds the old file when the name changes,
//! and a book without annotations has no file. Every generated file starts with
//! [`MARKER`]; only files with it are ever removed, so files the user put into the
//! folder are left alone.

use std::collections::HashSet;
use std::fmt::Write as _;
use std::io::{BufRead, Write as _};
use std::path::{Path, PathBuf};

use super::Annotation;
use super::text;
use crate::format::model::BlockId;

/// The first line of every generated file.
pub const MARKER: &str = "<!-- generated by shelfgauge, edits are overwritten -->";

/// The longest file name stem in code points (before the short key and extension).
const MAX_STEM_CHARS: usize = 120;

/// The book a file is about.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ExportBook {
    /// The content key.
    pub key: Vec<u8>,
    /// The book id links point to (the last known one).
    pub id: i64,
    /// The title.
    pub title: String,
    /// The authors, joined with `, `.
    pub authors: String,
    /// Whether no book in the library has this content any more (an orphan): the
    /// places of the quotes are not found.
    pub orphan: bool,
}

/// Writes and removes export files.
#[derive(Debug, Clone)]
pub struct Exporter {
    dir: PathBuf,
    base_url: String,
}

impl Exporter {
    /// An exporter into `dir`, linking to the reader at `base_url` (e.g.
    /// `http://127.0.0.1:8742/books`; a trailing slash is ignored).
    pub fn new(dir: impl Into<PathBuf>, base_url: &str) -> Self {
        Self {
            dir: dir.into(),
            base_url: base_url.trim_end_matches('/').to_owned(),
        }
    }

    /// The export folder.
    pub fn dir(&self) -> &Path {
        &self.dir
    }

    /// Rewrites the file of `book` with its live `annotations` (in book order), or
    /// removes it if there are none. Older files of the same book (other names) are
    /// removed; an unchanged file is not rewritten. Returns the path of the file.
    pub fn write(
        &self,
        book: &ExportBook,
        annotations: &[Annotation],
    ) -> std::io::Result<Option<PathBuf>> {
        let name = file_name(&book.title, &book.authors, &book.key);
        for old in self.files_of(&book.key)? {
            if old.file_name().is_some_and(|n| *n != *name) || annotations.is_empty() {
                remove_generated(&old)?;
            }
        }
        if annotations.is_empty() {
            return Ok(None);
        }
        std::fs::create_dir_all(&self.dir)?;
        let path = self.dir.join(&name);
        let markdown = render(book, annotations, &self.base_url);
        if std::fs::read(&path).is_ok_and(|old| old == markdown.as_bytes()) {
            return Ok(Some(path));
        }
        let mut file = tempfile::NamedTempFile::new_in(&self.dir)?;
        file.write_all(markdown.as_bytes())?;
        file.as_file().sync_all()?;
        file.persist(&path).map_err(|e| e.error)?;
        Ok(Some(path))
    }

    /// Removes the file(s) of the book with content key `key`.
    pub fn remove(&self, key: &[u8]) -> std::io::Result<()> {
        for path in self.files_of(key)? {
            remove_generated(&path)?;
        }
        Ok(())
    }

    /// Removes generated files that are not in `keep`; returns how many were removed.
    pub fn remove_stale(&self, keep: &HashSet<PathBuf>) -> std::io::Result<usize> {
        let mut removed = 0;
        for path in self.markdown_files()? {
            if !keep.contains(&path) && is_generated(&path) {
                std::fs::remove_file(&path)?;
                removed += 1;
            }
        }
        Ok(removed)
    }

    /// Generated files named with the short key of `key`.
    fn files_of(&self, key: &[u8]) -> std::io::Result<Vec<PathBuf>> {
        let tail = format!("({}).md", short_key(key));
        Ok(self
            .markdown_files()?
            .into_iter()
            .filter(|p| {
                p.file_name()
                    .and_then(|n| n.to_str())
                    .is_some_and(|n| n.ends_with(&tail))
            })
            .filter(|p| is_generated(p))
            .collect())
    }

    fn markdown_files(&self) -> std::io::Result<Vec<PathBuf>> {
        let entries = match std::fs::read_dir(&self.dir) {
            Ok(entries) => entries,
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(Vec::new()),
            Err(e) => return Err(e),
        };
        let mut files = Vec::new();
        for entry in entries {
            let entry = entry?;
            let path = entry.path();
            if entry.file_type()?.is_file() && path.extension().is_some_and(|e| e == "md") {
                files.push(path);
            }
        }
        files.sort();
        Ok(files)
    }
}

/// Whether the file starts with [`MARKER`].
fn is_generated(path: &Path) -> bool {
    let Ok(file) = std::fs::File::open(path) else {
        return false;
    };
    let mut line = String::new();
    std::io::BufReader::new(file).read_line(&mut line).is_ok() && line.trim_end() == MARKER
}

fn remove_generated(path: &Path) -> std::io::Result<()> {
    match std::fs::remove_file(path) {
        Err(e) if e.kind() != std::io::ErrorKind::NotFound => Err(e),
        _ => Ok(()),
    }
}

/// 8 hex digits identifying a content key in file names.
pub fn short_key(key: &[u8]) -> String {
    format!("{:08x}", xxhash_rust::xxh3::xxh3_64(key) as u32)
}

/// The export file name of a book: `<Authors> — <Title> (<short key>).md`, safe on
/// every platform.
///
/// # Examples
///
/// ```
/// use shelfgauge::annotations::export::file_name;
///
/// let name = file_name("A/B: C?", "Lev Tolstoy", b"key");
/// assert!(name.starts_with("Lev Tolstoy — A_B_ C_ ("), "{name}");
/// assert!(name.ends_with(").md"));
/// ```
pub fn file_name(title: &str, authors: &str, key: &[u8]) -> String {
    let stem = match (authors.trim(), title.trim()) {
        ("", title) => title.to_owned(),
        (authors, title) => format!("{authors} — {title}"),
    };
    let mut stem = sanitize(&stem);
    if text::char_len(&stem) > MAX_STEM_CHARS {
        stem = text::first_chars(&stem, MAX_STEM_CHARS)
            .trim_end_matches([' ', '.'])
            .to_owned();
    }
    if stem.is_empty() {
        stem = "Untitled".to_owned();
    }
    format!("{stem} ({}).md", short_key(key))
}

/// Replaces characters that are not allowed (or not safe) in file names, collapses
/// whitespace, and avoids Windows device names and names starting with a dot.
fn sanitize(name: &str) -> String {
    let replaced: String = name
        .chars()
        .map(|c| match c {
            '<' | '>' | ':' | '"' | '/' | '\\' | '|' | '?' | '*' => '_',
            c if c.is_control() => ' ',
            c => c,
        })
        .collect();
    let mut name = replaced.split_whitespace().collect::<Vec<_>>().join(" ");
    name = name.trim_matches(['.', ' ']).to_owned();
    let device = name
        .split('.')
        .next()
        .unwrap_or("")
        .trim()
        .to_ascii_uppercase();
    let reserved = matches!(device.as_str(), "CON" | "PRN" | "AUX" | "NUL")
        || ((device.starts_with("COM") || device.starts_with("LPT"))
            && device.len() == 4
            && device.as_bytes()[3].is_ascii_digit());
    if reserved {
        name.insert(0, '_');
    }
    name
}

/// The Markdown of a book's annotations: title and authors, the bookmarks, then the
/// marks grouped by section, each a quote with its note and a link to the reader.
/// Quotes and notes are plain text paragraphs, not Markdown block quotes.
pub fn render(book: &ExportBook, annotations: &[Annotation], base_url: &str) -> String {
    let link = |block: BlockId| {
        format!(
            "{}/book/{}/read?at={block}&from=mark",
            base_url.trim_end_matches('/'),
            book.id
        )
    };
    let mut out = String::new();
    let _ = writeln!(out, "{MARKER}\n");
    let _ = writeln!(out, "# {}\n", inline(&book.title));
    if !book.authors.trim().is_empty() {
        let _ = writeln!(out, "{}\n", inline(&book.authors));
    }
    if book.orphan {
        let _ = writeln!(
            out,
            "**Place in the book not found:** the book's file has changed or is no \
             longer in the library. The quotes are kept; the links may not work.\n"
        );
    }
    let bookmarks: Vec<&Annotation> = annotations.iter().filter(|a| a.is_bookmark()).collect();
    let marks: Vec<&Annotation> = annotations.iter().filter(|a| !a.is_bookmark()).collect();
    if !bookmarks.is_empty() {
        let _ = writeln!(out, "## Bookmarks\n");
        for bookmark in bookmarks {
            let _ = writeln!(
                out,
                "- [{}]({})",
                inline(&bookmark.label()).replace(']', "\\]"),
                link(bookmark.anchor.start_block)
            );
        }
        out.push('\n');
    }
    if !marks.is_empty() {
        let _ = writeln!(out, "## Quotes\n");
        let mut section: Option<Option<&str>> = None;
        for mark in marks {
            let title = mark.section_title.as_deref();
            if section != Some(title) {
                if let Some(title) = title {
                    let _ = writeln!(out, "### {}\n", inline(title));
                }
                section = Some(title);
            }
            let _ = writeln!(out, "{}\n", mark.quote.text.trim());
            if let Some(note) = mark.note() {
                let _ = writeln!(out, "{}\n", note.trim());
            }
            let place = if mark.anchor_lost {
                "place not found"
            } else {
                "open"
            };
            let _ = writeln!(out, "[{place}]({})\n", link(mark.anchor.start_block));
        }
    }
    let trimmed = out.trim_end().len();
    out.truncate(trimmed);
    out.push('\n');
    out
}

/// Text for a single Markdown line (headings, list items): line breaks become spaces.
fn inline(text: &str) -> String {
    text.split_whitespace().collect::<Vec<_>>().join(" ")
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::annotations::tests::sample;

    fn book(title: &str) -> ExportBook {
        ExportBook {
            key: b"key".to_vec(),
            id: 12,
            title: title.into(),
            authors: "A. Author".into(),
            orphan: false,
        }
    }

    #[test]
    fn content_bookmarks_first_then_marks_by_section() {
        let mut quote = sample("First line\nsecond line", Some("My note"));
        quote.anchor.start_block = BlockId::new(40).unwrap();
        let mut other = sample("Elsewhere", None);
        other.section_title = Some("Chapter 2".into());
        other.anchor_lost = true;
        let bookmark = sample("", None);
        let md = render(
            &book("The Book"),
            &[quote, bookmark, other],
            "http://127.0.0.1:8742/",
        );
        assert!(
            md.starts_with(&format!("{MARKER}\n\n# The Book\n\nA. Author\n")),
            "{md}"
        );
        let bookmarks = md.find("## Bookmarks").unwrap();
        let marks = md.find("## Quotes").unwrap();
        assert!(bookmarks < marks, "{md}");
        assert!(
            md.contains(
                "- [Chapter 1 — It was a dark and stormy night; the rain fell in torrents, except…]\
                 (http://127.0.0.1:8742/book/12/read?at=b3&from=mark)"
            ),
            "{md}"
        );
        assert!(md.contains("### Chapter 1\n\nFirst line\nsecond line\n\nMy note\n\n[open](http://127.0.0.1:8742/book/12/read?at=b40&from=mark)"), "{md}");
        assert!(
            md.contains("### Chapter 2\n\nElsewhere\n\n[place not found]("),
            "{md}"
        );
        assert!(!md.contains("not found:**"), "not an orphan");
        assert!(
            !md.lines().any(|l| l.starts_with('>')),
            "no block quotes: {md}"
        );
        assert!(md.ends_with(")\n"), "{md:?}");

        let mut orphan = book("The Book");
        orphan.orphan = true;
        let md = render(&orphan, &[sample("x", None)], "http://h");
        assert!(md.contains("\n**Place in the book not found:**"), "{md}");
        assert!(
            !md.lines().any(|l| l.starts_with('>')),
            "no block quotes: {md}"
        );
        assert!(!md.contains("## Bookmarks"), "{md}");
    }

    #[test]
    fn file_names_are_safe_everywhere() {
        let name = file_name("  CON  ", "", b"k");
        assert!(name.starts_with("_CON ("), "{name}");
        assert!(file_name("com1.txt", "", b"k").starts_with("_com1.txt ("));
        assert!(file_name("COMMA", "", b"k").starts_with("COMMA ("));
        assert!(file_name("...", "", b"k").starts_with("Untitled ("));
        let name = file_name("a\tb\nc*?<>|\"\\", "x", b"k");
        assert!(name.starts_with("x — a b c_______ ("), "{name}");
        let long = file_name(&"слово ".repeat(100), "", b"k");
        assert!(text::char_len(&long) <= MAX_STEM_CHARS + 16, "{long}");
        // The same title and authors with different content: different files.
        assert_ne!(file_name("T", "A", b"k1"), file_name("T", "A", b"k2"));
        assert_eq!(short_key(b"k1").len(), 8);
    }

    #[test]
    fn write_rename_and_remove() {
        let dir = tempfile::tempdir().unwrap();
        let exporter = Exporter::new(dir.path().join("annotations"), "http://h");
        let a = [sample("quote", None)];
        let first = exporter.write(&book("Old title"), &a).unwrap().unwrap();
        assert!(first.is_file());
        assert!(is_generated(&first));
        // A user's own file with a matching name is never touched.
        let mine = exporter
            .dir()
            .join(format!("Mine ({}).md", short_key(b"key")));
        std::fs::write(&mine, "my notes").unwrap();
        // Rewrite in place.
        assert_eq!(
            exporter.write(&book("Old title"), &a).unwrap(),
            Some(first.clone())
        );
        // Renamed book: the old file goes.
        let second = exporter.write(&book("New title"), &a).unwrap().unwrap();
        assert_ne!(first, second);
        assert!(!first.exists() && second.is_file());
        // No annotations left: no file.
        assert_eq!(exporter.write(&book("New title"), &[]).unwrap(), None);
        assert!(!second.exists());
        assert!(mine.exists());

        let kept = exporter.write(&book("Kept"), &a).unwrap().unwrap();
        let mut other = book("Other");
        other.key = b"other".to_vec();
        let stale = exporter.write(&other, &a).unwrap().unwrap();
        let keep: HashSet<PathBuf> = [kept.clone()].into();
        assert_eq!(exporter.remove_stale(&keep).unwrap(), 1);
        assert!(kept.exists() && !stale.exists() && mine.exists());
        exporter.remove(b"key").unwrap();
        assert!(!kept.exists() && mine.exists());
        // No temporary files are left behind.
        let names: Vec<_> = std::fs::read_dir(exporter.dir()).unwrap().collect();
        assert_eq!(names.len(), 1);
    }
}
